------------ import ------------
local KTool = CS.Engine.Lib.KTool
local FishingUtils = import('Game.UI.Fishing.FishingUtils')
local fishingComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
------------ import ------------
local CommonGoodsList = "Game.Behaviours.CommonGoodsList"

---@class UIFishPoolContestRewardsPopupNode
---@field Env                           	UIFishPoolContestRewardsPopupNode                                     
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field FinishGroup                   	UnityEngine.RectTransform               
---@field TxtOngoing                    	UnityEngine.RectTransform               
---@field FontStyleButton               	UnityEngine.RectTransform               
---@field UIFX_ActivityCompletion       	UnityEngine.RectTransform               
---@field CommonGoodsList               	UnityEngine.RectTransform               
---@field TxtNumber                     	UnityEngine.RectTransform               
---@field Normal                        	UnityEngine.RectTransform                          
local UIFishPoolContestRewardsPopupNode = Class('UIFishPoolContestRewardsPopupNode')

function UIFishPoolContestRewardsPopupNode:__init()
    self._data = nil
    self._fishPlaceId = nil
end

function UIFishPoolContestRewardsPopupNode:__delete()
    self._data = nil
    self._fishPlaceId = nil
end

function UIFishPoolContestRewardsPopupNode:Awake()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnDrawReward))
end

---Refresh
---@param data table 
---@param isMe boolean 是否是自己 
function UIFishPoolContestRewardsPopupNode:Refresh(data, fishPlaceId)
    if not data then
        return
    end
    self._data = data
    self._fishPlaceId = fishPlaceId

    self:FillSelf()

    CfUtils.PlayAnimator(self.controller.gameObject, "Go")
end

function UIFishPoolContestRewardsPopupNode:FillSelf()
    CfUtils.FillText(self.TxtNumber, self._data.point)

    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsList)
    if scr then
        local t = parse_rewards(self._data.reward, self._data.rewardNum)
        scr:FreshBaseUI(t, false)
    end

    local isDraw = FishingUtils.IsDrawIntegralReward(self._fishPlaceId, self._data.id)
    local isCanDraw = FishingUtils.IsCanDrawIntegralReward(self._fishPlaceId, self._data.id)

    CfUtils.SetActive(self.FontStyleButton, isCanDraw and not isDraw)
    CfUtils.SetActive(self.TxtOngoing, not isCanDraw)
    CfUtils.SetActive(self.FinishGroup, isDraw)
end

function UIFishPoolContestRewardsPopupNode:OnDrawReward()
    local isDraw = FishingUtils.IsDrawIntegralReward(self._fishPlaceId, self._data.id)
    local isCanDraw = FishingUtils.IsCanDrawIntegralReward(self._fishPlaceId, self._data.id)

    if isDraw then
        GameUtils.Toast(localize("该奖励已领取"))
        return
    elseif not isCanDraw then
        GameUtils.Toast(localize("未满足条件"))
        return
    end

    fishingComponent:FishingReceiveScoreRewardsReq(self._fishPlaceId, self._data.id, function()
        self:FillSelf()
    end)
end

function UIFishPoolContestRewardsPopupNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFishPoolContestRewardsPopupNode
